export const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export function plusDays(key,n){const [y,m,d]=key.split('-').map(Number);return dayKey(new Date(y,m-1,d+n,12));}
export function initialState(){return {version:1,currentDay:1,tasks:{},assessments:{},reviews:{},reviewLog:[],activity:{},notes:{},todos:[],sessions:[],xpAwards:{},settings:{name:'Bongie',sound:true,volume:0.35,reducedMotion:false,theme:'light',focus:25,shortBreak:5,longBreak:15,startDate:'',ankiDeck:'Recall Forge',ankiUrl:'http://127.0.0.1:8765'},customTracks:[],customCards:[],lessonDone:{}};}
export function eraseProgress(s){const fresh=initialState();for(const key of ['settings','notes','todos','customTracks','customCards'])fresh[key]=structuredClone(s[key]??fresh[key]);return fresh;}
export function award(s,key,points){if(s.xpAwards[key])return false;s.xpAwards[key]=points;return true;}
export function xp(s){return Object.values(s.xpAwards).reduce((a,b)=>a+b,0);}
export function stats(s,today=dayKey()){let streak=0,k=s.activity[today]?today:plusDays(today,-1);while(s.activity[k]){streak++;k=plusDays(k,-1);}return {xp:xp(s),level:1+Math.floor(xp(s)/200),streak,completed:Object.values(s.tasks).filter(x=>x.backend&&x.dsa&&x.review).length,recall:Object.values(s.assessments).filter(x=>x.r).length,applied:Object.values(s.assessments).filter(x=>x.a).length};}
export function enroll(s,cardId,intervals,today=dayKey()){if(s.reviews[cardId])return;s.reviews[cardId]={id:cardId,learned:today,stage:0,due:plusDays(today,intervals[0]),guided:false,history:[]};}
export function grade(s,id,result,intervals,today=dayKey(),applied=false,guidedApplication=false){const r=s.reviews[id];if(!r)throw Error('Unknown review');if(r.history.some(x=>x.date===today))throw Error('Already reviewed today');const assessed=s.assessments[id]||{};assessed.r=result==='R';assessed.a=applied||assessed.a||false;assessed.g=result==='G'||guidedApplication;s.assessments[id]=assessed;r.history.push({date:today,result,applied,guidedApplication});r.guided=result==='G'||guidedApplication;if(result==='G'||guidedApplication){r.due=plusDays(today,1);}else{r.stage++;const target=intervals[r.stage];r.due=target?plusDays(r.learned,target):null;if(r.due&&r.due<=today)r.due=plusDays(today,1);}s.reviewLog.push({id,date:today,result,applied,guidedApplication});s.activity[today]=true;award(s,`review:${id}:${today}`,result==='R'?15:5);}
export function dueCards(s,today=dayKey()){return Object.values(s.reviews).filter(x=>x.due&&x.due<=today&&!x.history.some(h=>h.date===today)).sort((a,b)=>Number(b.guided)-Number(a.guided)||a.due.localeCompare(b.due)||a.id.localeCompare(b.id));}
export function validateTrack(t){if(!t||typeof t.id!=='string'||!/^[-a-zA-Z0-9_]{1,70}$/.test(t.id)||typeof t.title!=='string'||!t.title.trim()||t.title.length>150||!Array.isArray(t.lessons)||!t.lessons.length||t.lessons.length>1000)throw Error('Use a track id, title and 1–1,000 lessons.');const ids=new Set();for(const l of t.lessons){if(!l||typeof l.id!=='string'||ids.has(l.id)||typeof l.title!=='string'||!l.title.trim())throw Error('Every lesson needs a unique id and title.');ids.add(l.id);if(l.resource&&!/^https?:\/\//.test(l.resource))throw Error('Resource URLs must use http or https.');}return t;}
export function validateBackup(b){if(!Number.isInteger(b?.currentDay)||b.currentDay<1||b.currentDay>154||!Array.isArray(b.customCards)||typeof b.settings?.name!=='string'||!Number.isInteger(b.settings?.focus)||b.settings.focus<1||b.settings.focus>120)throw Error('Invalid current day, custom cards or focus preferences.');if(b?.version!==1||!b.tasks||!b.settings||!Array.isArray(b.customTracks)||!Array.isArray(b.reviewLog)||!b.reviews||!b.xpAwards||!Array.isArray(b.sessions))throw Error('This is not a Recall Forge version 1 backup.');for(const t of b.customTracks)validateTrack(t);for(const [id,r] of Object.entries(b.reviews)){if(r.id!==id||!Array.isArray(r.history)||!Number.isInteger(r.stage)||r.stage<0)throw Error('Invalid review data.');}if(Object.values(b.xpAwards).some(n=>!Number.isFinite(n)||n<0))throw Error('Invalid progress data.');return b;}
